questions.answer:
```cpp
// Returns the cell where x is (or the EMPTY cell that ends the search); firstInactive is set to the
// first EMPTY or DELETED cell on the probe path (the cell where a new x should go).
int findPos( const HashedObj & x, int & firstInactive ) const
{
    int offset = 1;
    int currentPos = myhash( x );
    firstInactive = -1;

    while( array[ currentPos ].info != EMPTY &&
           array[ currentPos ].element != x )
    {
        if( firstInactive == -1 && array[ currentPos ].info == DELETED )
            firstInactive = currentPos;          // remember the first tombstone we pass

        currentPos += offset;                    // ith probe
        offset += 2;
        if( currentPos >= array.size( ) )
            currentPos -= array.size( );
    }

    if( firstInactive == -1 )                    // no tombstone before the stopping cell:
        firstInactive = currentPos;              // it is EMPTY (or a DELETED cell holding x)
    return currentPos;
}

int findPos( const HashedObj & x ) const        // unchanged interface, used by contains/remove
{
    int dummy;
    return findPos( x, dummy );
}

bool insert( const HashedObj & x )
{
    int firstInactive;
    int currentPos = findPos( x, firstInactive );
    if( isActive( currentPos ) )
        return false;                            // already present

    bool reusedDeleted = ( array[ firstInactive ].info == DELETED );
    array[ firstInactive ].element = x;
    array[ firstInactive ].info = ACTIVE;

    // a reclaimed DELETED cell was already counted in currentSize
    if( !reusedDeleted && ++currentSize > array.size( ) / 2 )
        rehash( );
    return true;
}
```
Notes: the loop still runs to the EMPTY cell (or to x) so we know whether x is already in the table; only the *place of insertion* changes. A DELETED cell is skipped by the loop (it is not EMPTY and holds a different element). `remove` and `contains` are unchanged (`isActive( findPos( x ) )`).

